mapper.select:
WITH kw AS ( SELECT id, row_number() OVER (ORDER BY publish_date DESC NULLS LAST, created_at DESC) AS rank FROM documents d WHERE 1 = 1
), sem AS ( SELECT id, row_number() OVER (ORDER BY embedding <=> #{queryVector}::vector) AS rank FROM documents d WHERE d.embedding IS NOT NULL
), fused AS ( SELECT id, sum(1.0 / (60 + rank)) AS rrf FROM (SELECT id, rank FROM kw UNION ALL SELECT id, rank FROM sem) u GROUP BY id ) SELECT , f.rrf FROM documents d JOIN fused f ON f.id = d.id ORDER BY f.rrf DESC, d.publish_date DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}
